#!/usr/bin/env bash
# Round 393 PERF-13c-i claims (L29 + L56). Run from the loop root. CLAIMS_STORE overrides the store path.
L=$(pwd); S=${CLAIMS_STORE:-/home/runner/czaba-project/store}; C=$S/app/contexts/ArrangementContext.tsx; P=$S/app/lib/arrangement/preview.client.ts; TY=$S/app/types/arrangement.ts; D=$S/app/data/studio-lab-demo.ts; LP=$S/app/components/arrangement/ArrangementLibraryPreview.tsx
