echo "K3 $(cd $S && sha256sum -c $L/b-round-318/protected-sha256.txt 2>/dev/null | grep -c ': OK$')"
echo "K4 $(cd $S && sha256sum -c $L/b-round-392/r393-frozen-sha256.txt 2>/dev/null | grep -vc ': OK$') $(wc -l < b-round-392/r393-frozen-sha256.txt)"
