echo "K11 demo mp3-urls $(grep -cE "^  'demo-[a-z-]+': '/[^']+\.mp3',$" $D) canReload-by-urls $(grep -c 'canReloadSource: (source) => Object.hasOwn(demoUrls, source.id),' $D) previewUrl $(grep -c 'previewUrl' $D)"
