echo "K16 SWEEP demo-collection test users (roots app/** perf/** e2e/**): $(grep -rlE 'studioLabDemoCollection|studio-lab-demo' $S/app $S/perf $S/e2e --include=*.ts --include=*.tsx | grep -E '__tests__|/perf/|/e2e/' | sed "s#$S/##" | sort | tr '\n' ' ')"
