echo "K20 $(for f in tasks/round-392.md c-round-392.json c-round-392.md c-round-392/probe.mjs c-round-382/lib.mjs b-round-392/grants-393.txt b-round-392/r393-frozen-sha256.txt b-round-318/protected-sha256.txt b-round-392/premise/premise.mjs b-round-392/premise/premise-head.json b-round-392/sketch-393.patch.txt b-round-392/sketch-review.md b-round-392/mutants/summary.txt b-round-392/precheck-full.log b-round-392/sketch-browser.json b-round-392/claims-393.sh; do test -e $f || echo MISSING:$f; done; echo checked)"
