echo "K26 budgets $(python3 -I -c "import json;d={r['id']:r for r in json.load(open('$S/perf/budgets.resources.json'))};print(*[(d[k]['mode'],d[k]['budget']['value'] if d[k]['budget'] else None) for k in ('res.mem.pcm-live-mib-ready','res.mem.pcm-live-decode-mib-ready')])") purchased-adapter $(grep -c 'const url = stemUrls.get(source.id);' $S/app/lib/arrangement/collection.ts)"
